B.a5l=s(["\uc9c1\uc811 \ub9cc\ub4e0\ub2e4\uba74 \ud1b1\ubc25(\ub610\ub294 \uba74\uc2e4\ud53c \ud3a0\ub9bf)\uacfc \uc300\uaca8(\ub610\ub294 \uba74\uc2e4\ubc15)\ub97c 8 : 2(\ubd80\ud53c \ube44\uc728)\ub85c \uc11e\uc5b4\uc694.","\uc5f4\uc5d0 \uacac\ub514\ub294 \ube44\ub2d0 \ubd09\uc9c0\uc5d0 \ubc30\uc9c0\ub97c 1~1.5kg\uc529 \ub123\uc5b4\uc694. \ub108\ubb34 \ub290\uc2a8\ud558\uba74 \uc218\ud655\ub7c9\uc774 \uc904\uace0, \ub108\ubb34 \ub2e8\ub2e8\ud558\uba74 \uade0\uc774 \ucc9c\ucc9c\ud788 \ud37c\uc9c4\ub2e4\uace0 \uc790\ub8cc\uc5d0 \ub098\uc640 \uc788\uc5b4\uc694.","\uc0b4\uade0\uc740 \uc0c1\uc555 98~100\u2103\ub85c 6~12\uc2dc\uac04, \ub610\ub294 \uace0\uc555 121\u2103\ub85c 60~90\ubd84\uc774\uc5d0\uc694.","\ucc98\uc74c\uc5d0\ub294 \ubc30\uc591\uacfc \uac08\ubcc0\uc774 \ub05d\ub09c \ubc30\uc9c0\ub97c \uc0ac \uc624\ub294 \ucabd\uc774 \uc2e4\ud328\uac00 \uc801\uc5b4\uc694(\uc77c\ubc18 \uc694\ub839)."],t.s)
B.aih=new A.aB("sh-p1",B.b1,null,"\ubc30\uc9c0 \uc900\ube44 \ubc29\ubc95 \uc815\ud558\uae30",30,B.pF,B.a5l,"\ubc30\uc9c0\ub97c \uc9c1\uc811 \ub9cc\ub4e4\uc9c0, \uc0ac \uc62c\uc9c0 \uc815\ud574\uc84c\uc5b4\uc694.","\uc124\ube44\uac00 \uc5c6\ub2e4\uba74 \ubc30\uc591\uae4c\uc9c0 \ub9c8\uce5c \ubc30\uc9c0\ub97c \ud30c\ub294 \uacf3\uc744 \ub18d\uc5c5\uae30\uc220\uc13c\ud130\uc5d0 \ubb38\uc758\ud574\uc694.",B.m,B.aw,0,null)
B.a3C=s(["\uc885\uade0","\uc18c\ub3c5\ud55c \ub3c4\uad6c\uc640 \uc637","\uc0b4\uade0\ub41c \ubd09\uc9c0 \ubc30\uc9c0"],t.s)
B.a0A=s(["\uc885\uade0\uc740 \ubc30\uc591 \uc77c\uc815\uc5d0 \ub9de\ucdb0 \uc8fc\ubb38\ud558\uace0, \ucc28\uac11\uace0 \uc5b4\ub450\uc6b4 \uacf3\uc5d0 \ubcf4\uad00\ud588\ub2e4\uac00 \ubc1b\uc740 \uc9c0 5~7\uc77c \uc548\uc5d0 \uc368\uc694.","\uc811\uc885\uc740 \uae68\ub057\ud55c \uacf5\uae30\uac00 \ub098\uc624\ub294 \ubc29\uc5d0\uc11c, \uc18c\ub3c5\ud55c \ub3c4\uad6c\uc640 \uc637\uc73c\ub85c \ud574\uc694.","\ubc30\uc591\uc740 \uc5b4\ub461\uac8c \ud574\uc694. \uade0\uc740 5~35\u2103\uc5d0\uc11c \uc790\ub77c\uace0 25~30\u2103\uac00 \uac00\uc7a5 \uc88b\uc544\uc694.","\uade0\uc774 \uc5f4\uc744 \ub0b4\uc11c \ubc29 \uc628\ub3c4\uac00 2~3\u2103 \uc624\ub97c \uc218 \uc788\uc73c\ub2c8, \ubc29 \uc628\ub3c4\ub97c \uadf8\ub9cc\ud07c \ub0ae\uac8c \ub9de\ucdb0\uc694.","\ubc30\uc591\uc5d0 \uba70\uce60\uc774 \uac78\ub9ac\ub294\uc9c0\ub294 \uc790\ub8cc\uc5d0 \uc5c6\uc5b4\uc694. \ubc30\uc9c0 \uac89\uc774 \uac08\uc0c9\uc73c\ub85c \ubcc0\ud558\ub294 \uac83(\uac08\ubcc0)\uc744 \ub208\uc73c\ub85c \ud655\uc778\ud574\uc694."],t.s)
B.aiJ=new A.aB("sh-p2",B.b1,null,"\uc885\uade0\uacfc \ubc30\uc591 (\uc9c1\uc811 \ub9cc\ub4dc\ub294 \uacbd\uc6b0\ub9cc \ucc38\uace0)",60,B.a3C,B.a0A,"\ubc30\uc591 \uc911 \ubd09\uc9c0 \uc18d\uc5d0 \ud770 \uade0\uc774 \ud37c\uc9c0\uace0, \ub9c8\uc9c0\ub9c9\uc5d0 \uac89\uc774 \uac08\uc0c9\uc73c\ub85c \ubcc0\ud574\uc694.","\ud478\ub978\uc0c9\xb7\uac80\uc740\uc0c9 \uc5bc\ub8e9\uc774 \uc788\ub294 \ubd09\uc9c0\ub294 \ub530\ub85c \ube7c\uc11c \ubc84\ub824\uc694. \uc77c\uc218\ub294 \uad6c\uc785\ucc98 \uc548\ub0b4\ub97c \ud655\uc778\ud574\uc694.",B.m,B.aw,0,null)
B.a1i=s(["\uc628\ub3c4\uacc4","\uc2b5\ub3c4\uacc4","\uc870\ub3c4\uacc4(\uc788\ub2e4\uba74)","\uac00\uc2b5\uae30 \ub610\ub294 \ubb3c\ubfcc\ub9ac\uac1c"],t.s)
B.a5m=s(["\ubc1c\uc0dd\uc2e4(\ubc84\uc12f\uc774 \uc62c\ub77c\uc624\ub294 \ubc29)\uacfc \uc120\ubc18\uc744 \uccad\uc18c\ud574\uc694.","\uc628\ub3c4 15\xb13\u2103(12~18\u2103), \uc2b5\ub3c4 \uc57d 90%, \ubc1d\uae30 \uc57d 200lux(\uc2e0\ubb38\uc774 \uaca8\uc6b0 \uc77d\ud790 \ub9cc\ud55c \uc740\uc740\ud55c \ubc1d\uae30)\ub97c \ub9de\ucd9c \uc218 \uc788\ub294\uc9c0 \ud558\ub8e8 \uc2dc\ud5d8 \uc6b4\uc804\ud574\uc694.","\uac00\uc2b5\uae30\ub098 \ubb3c\ubfcc\ub9ac\uac1c, \ud658\uae30 \ub3c4\uad6c\ub97c \uc900\ube44\ud574\uc694. \ud658\uae30\ub7c9 \uae30\uc900\uc740 \uc790\ub8cc\uc5d0 \uc5c6\uc5b4\uc694."],t.s)
B.ahD=new A.aB("sh-p3",B.b1,null,"\ubc1c\uc0dd\uc2e4 \uc900\ube44\uc640 \uc2dc\ud5d8 \uc6b4\uc804",60,B.a1i,B.a5m,"\uc2dc\ud5d8 \uc6b4\uc804 \ub3d9\uc548 \uc628\ub3c4\xb7\uc2b5\ub3c4\xb7\ubc1d\uae30\uac00 \uae30\uc900 \uc548\uc5d0\uc11c \uc548\uc815\uc801\uc774\uc5d0\uc694.","\uc628\ub3c4\uac00 \ud754\ub4e4\ub9ac\uba74 \ub09c\ubc29\xb7\ub0c9\ubc29\uacfc \ubb38\ud2c8\uc744 \uace0\uce58\uace0 \ub2e4\uc2dc \uc2dc\ud5d8\ud574\uc694.",B.m,B.aw,0,"\uc628\xb7\uc2b5\ub3c4\uacc4\ub97c \uac78\uc5b4 \ub454 \ubc1c\uc0dd\uc2e4")
