B.a3w=s(["\ubc1c\uc774 \uc628\ub3c4\uac00 \ub9de\uc9c0 \uc54a\uc744 \uc218 \uc788\uc5b4\uc694. \uc790\ub8cc\uc5d0\uc11c \ubc84\uc12f \ubc1c\uc0dd\uc758 \uac00\uc7a5 \uc911\uc694\ud55c \uc870\uac74\uc774 \uc628\ub3c4 \uad00\ub9ac\uc608\uc694.","\uc2b5\ub3c4\uac00 90~95%\uc5d0 \ubabb \ubbf8\uce60 \uc218 \uc788\uc5b4\uc694.","\ube5b\uc774 \ub108\ubb34 \uc57d\ud560 \uc218 \uc788\uc5b4\uc694."],t.s)
B.a5f=s(["\ubc1c\uc774\uc2e4 \uc628\ub3c4(10~16\u2103)\uc640 \uc2b5\ub3c4(90~95%) \uae30\ub85d\uc744 \ubd10\uc694.","\uc2e0\ubb38\uc774 \uc77d\ud790 \uc815\ub3c4\ub85c \ubc1d\uc740\uc9c0 \ubd10\uc694.","\ubc30\uc591\uc774 \ucda9\ubd84\ud788 \ub05d\ub0ac\ub294\uc9c0(15~20\uc77c) \ubd10\uc694."],t.s)
