B.adb=s(["\uacfc\uc2b5\uacfc \uac74\uc870\uac00 \ubc18\ubcf5\ub410\uc744 \uc218 \uc788\uc5b4\uc694.","\ud759 \uc0b0\ub3c4(pH)\uac00 \ub0ae\uc744 \uc218 \uc788\uc5b4\uc694(\uc801\uc815 6.0~6.5).","\ub0ae\uc5d0 \ud558\uc6b0\uc2a4 \uc548\uc774 \ub108\ubb34 \ub728\uac70\uc6e0\uc744 \uc218 \uc788\uc5b4\uc694.","\ub545 \uc628\ub3c4\uac00 \ub192\uc558\uc744 \uc218 \uc788\uc5b4\uc694."],t.s)
B.aa0=s(["\ud759 \uc218\ubd84\uc774 \ub4e4\ucb49\ub0a0\ucb49\ud588\ub294\uc9c0 \uae09\uc218 \uae30\ub85d\uc744 \ubd10\uc694.","pH\ub97c \uc7ac \ubd10\uc694.","\ud55c\ub0ae \ud558\uc6b0\uc2a4 \uc548 \uc628\ub3c4\ub97c \ud655\uc778\ud574\uc694."],t.s)
B.a1o=s(["\uc5ec\ub984\uc5d0\ub294 \uc624\uc804 10\uc2dc~\uc624\ud6c4 4\uc2dc\uc5d0 \ucc28\uad11\ub9c9(20~40%)\uc744 \ub2eb\uace0 \uc5f4 \ub54c\ub97c \ub098\ub220\uc694.","\uc548\uac1c \ubd84\ubb34(\ud3ec\uadf8) \uc2dc\uc124\uacfc \ud658\uae30\ud32c\uc73c\ub85c \uc628\ub3c4\ub97c \ub0ae\ucdb0\uc694.","\uc218\ubd84\uc774 \uae09\uaca9\ud788 \ubcc0\ud558\uc9c0 \uc54a\uac8c \uafb8\uc900\ud788 \uad00\ub9ac\ud574\uc694."],t.s)
B.acy=s(["\ud1a0\uc591 \uac80\uc815 \uacb0\uacfc\uc5d0 \ub9de\ucdb0 \ubc11\uac70\ub984\uc744 \uc918\uc694.","\ubccf\uc9da\xb7\uc655\uaca8 \uac19\uc740 \uc720\uae30\ubb3c\uc744 \ub9e4\ub144 \ub123\uc5b4\uc694.","\ud55c\ub0ae \uc628\ub3c4\ub97c \uae30\ub85d\ud558\uace0 \ucc28\uad11 \uc2dc\uac04\uc744 \uc815\ud574 \ub450\uc5b4\uc694."],t.s)
