B.a3D=s(["\ubb3c\uc774 \ub108\ubb34 \ub9ce\uac70\ub098 \uc801\uc744 \uc218 \uc788\uc5b4\uc694.","\ubfcc\ub9ac\uac00 \uc0c1\ud588\uc744 \uc218 \uc788\uc5b4\uc694.","\uc591\ubd84\uc774 \ubaa8\uc790\ub784 \uc218 \uc788\uc5b4\uc694.","\ubcd1\uc774 \uc788\uc744 \uc218 \uc788\uc5b4\uc694."],t.s)
B.ad6=s(["\ud759\uc774 \uc9c8\ucc99\ud55c\uc9c0 \ub9d0\ub790\ub294\uc9c0 \ubd10\uc694.","\ubfcc\ub9ac\uac00 \ud558\uc580\uc9c0 \uac08\uc0c9\uc778\uc9c0 \ud55c \ud3ec\uae30\ub9cc \ubf51\uc544 \ubd10\uc694.","\uc544\ub798 \uc78e\ubd80\ud130 \ub178\ub798\uc9c0\ub294\uc9c0, \uc804\uccb4\uac00 \ub178\ub798\uc9c0\ub294\uc9c0 \ubd10\uc694."],t.s)
B.a6C=s(["\ubb3c\uc774 \ub9ce\uc73c\uba74 \uae09\uc218\ub97c \uc904\uc774\uace0 \ud658\uae30\ub97c \ub298\ub824\uc694.","\ubfcc\ub9ac\uac00 \uac08\uc0c9\uc774\uba74 \u201c\ubfcc\ub9ac \uc369\uc74c\u201d\uc744 \uc758\uc2ec\ud558\uace0 \uadf8 \ud3ec\uae30\ub97c \uce58\uc6cc\uc694.","\uc591\ubd84 \ubd80\uc871\uc774 \uc758\uc2ec\ub418\uba74 \ud1a0\uc591 \uac80\uc815\uc744 \ubc1b\uc544\uc694."],t.s)
