B.TR=new A.bT(14,"\uc624\ud6c4 2\uc2dc","\uc628\ub3c4\xb7\uc2dc\ub4e6 \ud655\uc778","\ub0ae\uc5d0 \uc78e\uc774 \ucc98\uc9c0\ub294\uc9c0, \ub0ae \uc628\ub3c4\uac00 30\u2103\ub97c \ub118\ub294\uc9c0","\ub118\uc73c\uba74 \ud658\uae30\xb7\ucc28\uad11\uc744 \ub298\ub824\uc694",B.R,B.q)
B.U7=new A.bT(16,"\uc624\ud6c4 4\uc2dc","\uc218\ud655","\uc544\ub798 \uc78e\uc774 \uc54c\ub9de\uc740 \ud06c\uae30\uc778\uc9c0(\uc218\ud655\uc740 4~7\uc77c \ub610\ub294 7~10\uc77c \uac04\uaca9)","\uc704\ucabd \uc5b4\ub9b0\uc78e 2~4\uc7a5\uc740 \ub0a8\uae30\uace0 \uc544\ub798 \uc78e\ubd80\ud130 \ub530\uc694",B.m,B.AT)
