B.a1R=s(["\uc2b5\ub3c4\uac00 \ub192\uace0 \ud658\uae30\uac00 \ubd80\uc871\ud560 \uc218 \uc788\uc5b4\uc694.","\uc78e\uc774 \uc816\uc740 \ucc44 \ubc24\uc744 \ubcf4\ub0c8\uc744 \uc218 \uc788\uc5b4\uc694.","\uc2dc\uc124 \uae7b\uc78e\uc5d0\uc11c \uacbd\uc81c\uc801\uc73c\ub85c \uc911\uc694\ud55c \ubcd1\uc774\ub77c\uace0 \uc790\ub8cc\uc5d0 \ub098\uc640 \uc788\uc5b4\uc694."],t.s)
B.a2V=s(["\ud658\uae30 \uc2dc\uac04\uacfc \ucc9c\uc7a5 \ubb3c\ubc29\uc6b8(\uacb0\ub85c)\uc744 \ubd10\uc694.","\ud3ec\uae30 \uc544\ub798\ucabd \uc78e\uc5d0 \ud68c\uc0c9 \uac00\ub8e8\uac00 \uc788\ub294\uc9c0 \ubd10\uc694.","\uac19\uc740 \uacf3\uc5d0\uc11c\ub9cc \ubc88\uc9c0\ub294\uc9c0 \ubd10\uc694."],t.s)
