B.a77=s(["\uc904\uae30 \uae38\uc774, \ubfcc\ub9ac \uae38\uc774, \uc78e \uc218\ub97c \uba87 \ud3ec\uae30\ub9cc \uace8\ub77c \uc7ac\uc11c \uae30\ub85d\ud574\uc694(\ub17c\ubb38\uc774 \uc7b0 \ud56d\ubaa9\uc774\uc5d0\uc694).","\uc369\uc740 \ubb18\uc0bc\uc774\ub098 \uac08\uc0c9\uc73c\ub85c \ubb34\ub978 \ubfcc\ub9ac\uac00 \uc788\ub294\uc9c0 \ucc3e\uc544\ubd10\uc694(\ub17c\ubb38\uc740 \uc369\ub294 \ube44\uc728\ub3c4 \uce21\uc815\ud588\uc5b4\uc694).","\uc369\uc740 \uac83\uc740 \ubc14\ub85c \ube7c\ub0b4 \ub2e4\ub978 \ubb18\uc0bc\uc5d0 \ubc88\uc9c0\uc9c0 \uc54a\uac8c \ud574\uc694."],t.s)
B.ahA=new A.aB("sg-g3",B.aP,"grow","\uc0dd\uc721 \uae30\ub85d\uacfc \uc369\uc74c \uc810\uac80 (3\uc77c\ub9c8\ub2e4)",20,B.a8R,B.a77,"\uc904\uae30\uac00 \uace7\uace0 \uc78e\uc774 \ud3b4\uc9c0\uba70 \ubfcc\ub9ac\uac00 \ub2e8\ub2e8\ud574\uc694.","\uc369\uc74c\uc774 \ud37c\uc9c0\uba74 \ubb3c\uc744 \uac08\uace0 \ubca0\ub4dc\ub97c \uc53b\uc740 \ub4a4 \uc0c1\ud0dc \uc88b\uc740 \uac83\ub9cc \ub2e4\uc2dc \uc62c\ub824\uc694.",B.x,B.b8,3,"\uc815\uc0c1 \uc0c8\uc2f9\uc0bc\uacfc \uc369\uc740 \ubb18\uc0bc \ube44\uad50")
